const demo={papers:[{id:'paper-demo-2022',title:'真题 2022（示例）',exam_date:'2026-10-21',score:101,total_score:150,duration:136,source_name:'真题2022.pdf',import_status:'needs_review'},{id:'paper-demo-2021',title:'真题 2021（示例）',exam_date:'2026-10-17',score:96,total_score:150,duration:142,source_name:'真题2021.pdf',import_status:'analyzed'}],questions:[{id:'q-demo-01',paper_id:'paper-demo-2022',number:'18',subject:'高数',stem:'含参数定积分的换元与上下限处理',score_earned:4,max_score:5,correctness:'partial',review_status:'待诊断',error_stage:'',error_type:'',knowledge:'定积分｜换元｜上下限联动',fingerprint:{objects:['定积分'],method:['换元积分'],stages:['切入','计算']},notes:'做出了主体步骤，但换元后上下限漏改'},{id:'q-demo-02',paper_id:'paper-demo-2022',number:'19',subject:'线代',stem:'二次型正定性与正交变换',score_earned:2,max_score:5,correctness:'wrong',review_status:'待诊断',error_stage:'',error_type:'',knowledge:'二次型｜特征值｜正定性',fingerprint:{objects:['二次型','特征值'],method:['特征值判断'],stages:['切入','最终处理']},notes:'不会从题目条件判断切入方法'},{id:'q-demo-03',paper_id:'paper-demo-2022',number:'20',subject:'概率',stem:'分布函数与数字特征',score_earned:5,max_score:5,correctness:'correct',review_status:'高风险正确',error_stage:'',error_type:'',knowledge:'分布函数｜数字特征',fingerprint:{objects:['分布函数'],method:['数字特征公式'],stages:['切入','最终处理']},notes:'答对但用时 18 分钟且自信度低'},{id:'q-demo-04',paper_id:'paper-demo-2021',number:'17',subject:'高数',stem:'多元函数极值的条件判断',score_earned:0,max_score:5,correctness:'wrong',review_status:'已复盘',error_stage:'建模与路径',error_type:'方法不会',knowledge:'多元函数｜极值｜条件判断',fingerprint:{objects:['多元函数极值'],method:['拉格朗日乘子'],stages:['建模']},notes:'忽略了约束条件'},{id:'q-demo-05',paper_id:'paper-demo-2021',number:'22',subject:'概率',stem:'二维随机变量边缘分布',score_earned:3,max_score:5,correctness:'partial',review_status:'训练中',error_stage:'中间计算',error_type:'计算失误',knowledge:'二维随机变量｜边缘分布',fingerprint:{objects:['二维随机变量'],method:['边缘化'],stages:['建模','计算']},notes:'积分区域边界漏项'}],bank:[{id:'bank-calc-01',source:'本地示例题库',stem:'定积分换元：给定复合函数，判断换元变量与上下限',difficulty:2,tags:['定积分','换元','上下限联动'],fingerprint:{objects:['定积分'],method:['换元积分'],stages:['切入','计算']}},{id:'bank-calc-02',source:'本地示例题库',stem:'参数积分：换元后保留参数并判断积分区间',difficulty:3,tags:['定积分','参数','换元'],fingerprint:{objects:['定积分'],method:['换元积分'],stages:['切入','最终处理']}},{id:'bank-calc-03',source:'本地示例题库',stem:'积分区域变换：用极坐标计算二重积分',difficulty:3,tags:['重积分','换元','区域'],fingerprint:{objects:['重积分'],method:['极坐标'],stages:['建模','计算']}},{id:'bank-linear-01',source:'本地示例题库',stem:'二次型正定性：由特征值符号判断',difficulty:2,tags:['二次型','特征值','正定性'],fingerprint:{objects:['二次型'],method:['特征值判断'],stages:['切入','最终处理']}},{id:'bank-linear-02',source:'本地示例题库',stem:'二次型正交变换：构造标准形',difficulty:3,tags:['二次型','正交变换'],fingerprint:{objects:['二次型'],method:['正交变换'],stages:['建模','计算']}},{id:'bank-linear-03',source:'本地示例题库',stem:'含参数矩阵的特征值判断',difficulty:4,tags:['特征值','参数','正定性'],fingerprint:{objects:['特征值'],method:['特征值判断'],stages:['切入','最终处理']}},{id:'bank-prob-01',source:'本地示例题库',stem:'已知分布函数求概率与密度',difficulty:2,tags:['分布函数','密度'],fingerprint:{objects:['分布函数'],method:['分段积分'],stages:['切入','最终处理']}},{id:'bank-prob-02',source:'本地示例题库',stem:'联合密度求边缘密度',difficulty:3,tags:['二维随机变量','边缘分布'],fingerprint:{objects:['二维随机变量'],method:['边缘化'],stages:['建模','计算']}},{id:'bank-prob-03',source:'本地示例题库',stem:'数字特征综合计算',difficulty:2,tags:['数字特征','期望','方差'],fingerprint:{objects:['数字特征'],method:['数字特征公式'],stages:['计算','最终处理']}},{id:'bank-calc-04',source:'本地示例题库',stem:'中值定理：判断可用条件并定位结论',difficulty:2,tags:['中值定理','条件判断'],fingerprint:{objects:['中值定理'],method:['条件判断'],stages:['切入','最终处理']}}],profile:{stages:{'题目切入':{state:'不稳定',evidence:3,failures:2,successes:1},'建模与路径':{state:'重复失分',evidence:2,failures:2,successes:0},'中间计算':{state:'不稳定',evidence:2,failures:1,successes:1},'最终处理':{state:'未验证',evidence:0,failures:0,successes:0},'时间与审题':{state:'未验证',evidence:0,failures:0,successes:0}},repeated_errors:[{label:'方法不会',count:1},{label:'计算失误',count:1}]}};
let state=structuredClone(demo),activeFilter='all',activeQuestion=null,selectedStage='',selectedError='';
const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmtDate=v=>v?v.slice(5).replace('-','月')+'日':'待定';
async function loadState(){try{const r=await fetch('/api/bootstrap');if(!r.ok)throw Error();state=await r.json();$('connection-text').textContent='本地服务已连接';document.querySelector('.connection').classList.add('ok');$('data-mode').textContent='SQLite 本地数据'}catch{const saved=localStorage.getItem('mathlens-demo');if(saved)try{state=JSON.parse(saved)}catch{}$('connection-text').textContent='演示数据模式'}renderAll()}
async function post(path,body,opt={}){try{const r=await fetch(path,{method:'POST',headers:opt.form?undefined:{'Content-Type':'application/json'},body:opt.form?body:JSON.stringify(body)});if(!r.ok)throw Error();return await r.json()}catch{return null}}
function saveFallback(){localStorage.setItem('mathlens-demo',JSON.stringify(state))}
function renderStats(){const latest=[...state.papers].sort((a,b)=>(b.exam_date||'').localeCompare(a.exam_date||''))[0],queue=state.questions.filter(q=>['待诊断','高风险正确','不稳定'].includes(q.review_status)),repeated=state.profile?.repeated_errors?.reduce((s,x)=>s+x.count,0)||state.questions.filter(q=>q.error_type).length,recover=state.questions.reduce((s,q)=>s+Math.max(0,(q.max_score||0)-(q.score_earned||0)),0);$('stats').innerHTML=[['当前分数',`${latest?.score||0}<small> / ${latest?.total_score||150}</small>`,'最近一张试卷'],['待处理题',queue.length,'错题 + 高风险正确'],['重复错误',repeated,'来自已有证据'],['可回收分',`${recover.toFixed(1)}<small> 分</small>`,'按已录入题目']].map(x=>`<div class="stat"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-hint">${x[2]}</div></div>`).join('');$('queue-count').textContent=queue.length;$('hero-queue').textContent=queue.length}
function questionStatus(q){const map={'待诊断':'pending','高风险正确':'pending','不稳定':'pending','训练中':'training','已掌握':'done','已复盘':'done'};return`<span class="status ${map[q.review_status]||'pending'}">${esc(q.review_status||'待诊断')}</span>`}
function renderPriority(){const queue=state.questions.filter(q=>['待诊断','高风险正确','不稳定'].includes(q.review_status)).slice(0,4);$('priority-list').innerHTML=queue.length?queue.map(q=>`<div class="question-row" data-q="${q.id}"><span class="q-num">${esc(q.number)}</span><div><div class="q-title">${esc(q.subject)} · ${esc(q.stem)}</div><div class="q-meta">${esc(q.knowledge||'待提取')} · ${q.score_earned}/${q.max_score} 分</div></div><span class="q-score">${q.correctness==='correct'?'高风险':'需处理'}</span></div>`).join(''):'<div class="empty">当前没有待处理题目。导入新试卷或把已掌握题加入复测。</div>';document.querySelectorAll('[data-q]').forEach(el=>el.addEventListener('click',()=>openDrawer(el.dataset.q)))}
function renderLatest(){const latest=[...state.papers].sort((a,b)=>(b.exam_date||'').localeCompare(a.exam_date||''))[0];if(!latest){$('latest-paper').innerHTML='<div class="empty">还没有试卷，先导入一张已完成的 PDF。</div>';return}const percent=Math.round((latest.score||0)/(latest.total_score||150)*100);$('latest-paper').innerHTML=`<div class="latest-score"><strong>${latest.score||0}</strong><span>/ ${latest.total_score||150}</span></div><div class="latest-name">${esc(latest.title)}</div><div class="latest-meta"><span>${fmtDate(latest.exam_date)}</span><span>${latest.duration||'—'} 分钟</span><span>${latest.import_status==='analyzed'?'已分析':'待确认'}</span></div><div class="progress"><span style="width:${percent}%"></span></div><div class="latest-next">下一步：从题目队列挑选 3～5 道题，完成一次针对性检验。</div>`}
function renderPapers(){$('paper-count').textContent=`${state.papers.length} 张试卷`;$('papers-table').innerHTML=state.papers.length?state.papers.map(p=>`<tr><td class="paper-title-cell">${esc(p.title)}</td><td>${fmtDate(p.exam_date)}</td><td><strong>${p.score||'—'}</strong> / ${p.total_score||150}</td><td>${p.import_status==='analyzed'?'<span class="status done">已分析</span>':'<span class="status pending">待确认</span>'}</td><td>${esc(p.source_name||'手动录入')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">还没有试卷记录</td></tr>'}
function renderQueue(){let list=state.questions;if(activeFilter!=='all')list=list.filter(q=>q.review_status===activeFilter);$('queue-hint').textContent=`${list.length} 道题`;$('queue-list').innerHTML=list.length?list.map(q=>`<article class="queue-card" data-q="${q.id}"><div class="queue-card-head"><span class="eyebrow">${esc(q.subject)} · 第 ${esc(q.number)} 题</span>${questionStatus(q)}</div><h3>${esc(q.stem)}</h3><p>${esc(q.notes||'还没有诊断记录。点击进入题目工作台。')}</p><div class="card-tags"><span class="small-tag">${esc(q.knowledge||'待提取指纹')}</span>${q.error_stage?`<span class="small-tag">${esc(q.error_stage)}</span>`:''}<span class="small-tag">${q.score_earned}/${q.max_score} 分</span></div></article>`).join(''):'<div class="empty">这个筛选条件下没有题目。</div>';document.querySelectorAll('.queue-card').forEach(el=>el.addEventListener('click',()=>openDrawer(el.dataset.q)))}
function renderBank(){const query=($('bank-search')?.value||'').trim().toLowerCase(),stage=$('bank-stage')?.value||'',list=state.bank.filter(item=>{const blob=[item.stem,item.source,...(item.tags||[])].join(' ').toLowerCase();return(!query||blob.includes(query))&&(!stage||(item.fingerprint?.stages||[]).includes(stage))});$('bank-list').innerHTML=list.map(item=>`<article class="bank-card"><span class="eyebrow">${esc(item.source)}</span><h3>${esc(item.stem)}</h3><p>${(item.tags||[]).map(t=>`<span class="small-tag">${esc(t)}</span>`).join(' ')}</p><div class="bank-card-foot"><span class="difficulty">难度 ${'●'.repeat(item.difficulty||3)}${'○'.repeat(5-(item.difficulty||3))}</span><button class="candidate-open" data-bank="${item.id}">查看题目</button></div></article>`).join('')||'<div class="empty">没有匹配题目。可以换一个知识点或环节。</div>'}
function renderProfile(){const stages=state.profile?.stages||{};$('stage-list').innerHTML=Object.entries(stages).map(([name,x])=>`<div class="stage-row"><div><div class="stage-name">${esc(name)}</div><div class="stage-meta">证据 ${x.evidence||0} · 失败 ${x.failures||0} · 成功 ${x.successes||0}</div></div><span class="state ${x.state==='不稳定'||x.state==='重复失分'?'unstable':x.state==='基本掌握'||x.state==='迁移通过'?'ok':'unknown'}">${esc(x.state)}</span></div>`).join('');const errors=state.profile?.repeated_errors||[];$('error-list').innerHTML=errors.length?errors.map(x=>`<div class="error-row"><div><div class="error-name">${esc(x.label)}</div><div class="error-meta">重复出现 ${x.count} 次</div></div><span class="risk">优先处理</span></div>`).join(''):'<div class="empty">积累更多题目证据后，这里会显示重复错误。</div>'}
function renderPaperActions(){const table=document.querySelector('#papers-table');if(!table)return;const head=table.closest('table')?.querySelector('thead tr');if(head&&!head.querySelector('.paper-action-head')){const th=document.createElement('th');th.className='paper-action-head';th.textContent='操作';head.appendChild(th)}[...table.querySelectorAll('tr')].forEach((row,i)=>{if(row.querySelector('.paper-action-cell'))return;const paper=state.papers[i];if(!paper)return;const td=document.createElement('td');td.className='paper-action-cell';if(paper.import_status==='analyzed'){td.innerHTML='<span class="muted">已完成</span>'}else{const button=document.createElement('button');button.className='candidate-open';button.textContent='确认题目';button.addEventListener('click',()=>openConfirmPaper(paper.id));td.appendChild(button)}row.appendChild(td)})}
function openConfirmPaper(paperId){const paper=state.papers.find(p=>p.id===paperId);if(!paper)return;$('drawer-title').textContent='确认题目切分';$('drawer-body').innerHTML=`<div class="drawer-section" style="margin-top:0;padding-top:0;border-top:0"><div class="drawer-question"><strong>${esc(paper.title)}</strong><br><span>当前第一版先由你确认题号和分值，之后才进入逐题诊断。</span></div></div><div class="drawer-section"><h3>题号</h3><input id="confirm-numbers" class="confirm-input" placeholder="例如：1,2,3,4,5,6" /><p class="muted">可以填写 1,2,3，也可以填写 选择1,选择2,填空1。</p></div><div class="drawer-section"><h3>每题分值</h3><input id="confirm-scores" class="confirm-input" placeholder="例如：5,5,10,10，或只填一个统一分值" value="5" /><p class="muted">如果所有题分值相同，只填一个数字即可。</p></div><div class="drawer-section"><h3>科目</h3><select id="confirm-subject" class="confirm-input"><option>数学一</option><option>高数</option><option>线性代数</option><option>概率论</option></select><div class="drawer-footer"><button class="btn primary" id="confirm-paper-btn">生成题目队列</button></div></div>`;$('drawer-backdrop').classList.add('open');$('confirm-paper-btn').addEventListener('click',async()=>{const numbers=$('confirm-numbers').value.split(',').map(x=>x.trim()).filter(Boolean),scores=$('confirm-scores').value.split(',').map(x=>x.trim()).filter(Boolean);if(!numbers.length){$('confirm-numbers').focus();return}const response=await post(`/api/papers/${paperId}/confirm`,{numbers,scores,subject:$('confirm-subject').value});if(response){$('drawer-body').innerHTML=`<div class="success-note">已生成 ${response.created_questions} 道题目。现在可以进入“题目队列”逐题诊断。</div><div class="drawer-footer"><button class="btn primary" id="go-queue">打开题目队列</button></div>`;$('go-queue').addEventListener('click',()=>{$('drawer-backdrop').classList.remove('open');switchView('queue');loadState()})}else{$('drawer-body').insertAdjacentHTML('beforeend','<div class="success-note" style="background:var(--red-soft);color:var(--red)">保存失败，请确认本地服务仍在运行。</div>')}})}
function renderAll(){renderStats();renderPriority();renderLatest();renderPapers();renderPaperActions();renderQueue();renderBank();renderProfile()}
function switchView(view){const names={home:['今日工作','今日工作 / 待处理'],papers:['试卷','试卷 / 已完成材料'],queue:['题目队列','题目队列 / 逐题处理'],bank:['本地题库','本地题库 / 检索验证'],profile:['个人画像','个人画像 / 证据状态']};document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${view}`));document.querySelectorAll('.nav-item').forEach(v=>v.classList.toggle('active',v.dataset.view===view));$('page-title').textContent=names[view][0]==='今日工作'?'今天只处理最值得回收的分':names[view][0];$('crumb').textContent=names[view][1]}
function openDrawer(id){activeQuestion=state.questions.find(q=>q.id===id);if(!activeQuestion)return;selectedStage=activeQuestion.error_stage||'';selectedError=activeQuestion.error_type||'';$('drawer-title').textContent=`第 ${activeQuestion.number} 题 · ${activeQuestion.subject}`;$('drawer-body').innerHTML=drawerTemplate(activeQuestion);$('drawer-backdrop').classList.add('open');bindDrawer()}
function drawerTemplate(q){const fp=q.fingerprint||{},candidate=state.bank.filter(b=>{const blob=[b.stem,...(b.tags||[])].join(' ').toLowerCase();return(q.knowledge||'').split('｜').some(k=>blob.includes(k.toLowerCase()))||((b.fingerprint?.method||[]).some(x=>(fp.method||[]).includes(x)))}).slice(0,4);return`<div class="drawer-section" style="margin-top:0;padding-top:0;border-top:0"><div class="drawer-question"><strong>${esc(q.stem)}</strong><br><span>得分 ${q.score_earned}/${q.max_score} · ${esc(q.notes||'暂无批注')}</span></div></div><div class="drawer-section"><h3>先标记主要错误环节</h3><div class="option-grid stage-options">${['题目切入','建模与路径','中间计算','最终处理','时间与审题'].map(x=>`<button class="option ${selectedStage===x?'selected':''}" data-stage="${x}">${x}</button>`).join('')}</div></div><div class="drawer-section"><h3>错误主因</h3><div class="option-grid error-options">${['概念不清','方法不会','变式不会','计算失误','审题表达'].map(x=>`<button class="option ${selectedError===x?'selected':''}" data-error="${x}">${x}</button>`).join('')}</div></div><div class="drawer-section"><h3>诊断备注</h3><textarea id="diagnosis-notes" placeholder="写下证据：当时怎么想、卡在哪里、看答案后是否能独立重做">${esc(q.notes||'')}</textarea><div class="drawer-footer"><button class="btn primary" id="save-diagnosis">保存诊断并检索题目</button></div></div><div class="drawer-section"><div class="panel-head"><h3>推荐验证题</h3><span class="muted">${candidate.length} 道</span></div><div id="candidate-list">${candidate.length?candidate.map(c=>`<div class="candidate"><div><strong>${esc(c.stem)}</strong><span>${(c.tags||[]).join(' · ')} · 难度 ${c.difficulty}</span></div><button data-review="${c.id}">开始检验</button></div>`).join(''):'<div class="empty">暂时没有匹配题目，请先完善题目指纹。</div>'}</div></div>`}
function bindDrawer(){document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{selectedStage=b.dataset.stage;document.querySelectorAll('[data-stage]').forEach(x=>x.classList.toggle('selected',x===b))}));document.querySelectorAll('[data-error]').forEach(b=>b.addEventListener('click',()=>{selectedError=b.dataset.error;document.querySelectorAll('[data-error]').forEach(x=>x.classList.toggle('selected',x===b))}));$('save-diagnosis').addEventListener('click',async()=>{const body={review_status:'训练中',error_stage:selectedStage,error_type:selectedError,notes:$('diagnosis-notes').value};const response=await post(`/api/questions/${activeQuestion.id}/diagnose`,body);Object.assign(activeQuestion,body);if(response?.profile)state.profile=response.profile;saveFallback();renderAll();$('save-diagnosis').textContent='已保存';setTimeout(()=>{if(activeQuestion)openDrawer(activeQuestion.id)},250)});document.querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',()=>showReviewForm(b.dataset.review)))}
function showReviewForm(bankId){const bank=state.bank.find(x=>x.id===bankId);if(!bank)return;const host=$('candidate-list');host.innerHTML=`<div class="drawer-question"><strong>${esc(bank.stem)}</strong><br><span>请先独立作答，再记录结果。</span></div><div class="review-form" style="margin-top:10px"><label>结果<select id="review-correct"><option value="1">做对</option><option value="0">做错</option></select></label><label>用时（分钟）<input id="review-elapsed" type="number" value="8" /></label><label>自信度<select id="review-confidence"><option value="1">低</option><option value="2">中</option><option value="3">高</option></select></label></div><label style="display:block;margin-top:10px;font-size:9px;color:var(--muted)">是否通过变式迁移？<select id="review-transfer" style="margin-left:8px;border:1px solid #dce8e3;border-radius:7px;padding:7px;font:inherit;font-size:10px"><option value="0">暂未验证</option><option value="1">是，能独立迁移</option></select></label><div class="drawer-footer"><button class="btn primary" id="save-review">保存本次检验</button></div>`;$('save-review').addEventListener('click',async()=>{const body={question_id:activeQuestion.id,bank_question_id:bank.id,correct:$('review-correct').value==='1',elapsed:Number($('review-elapsed').value),confidence:Number($('review-confidence').value),transfer:$('review-transfer').value==='1',error_stage:selectedStage};const response=await post('/api/reviews',body);activeQuestion.review_status=body.correct&&(body.transfer?'已掌握':'训练中');if(!body.correct)activeQuestion.review_status='不稳定';if(response?.profile)state.profile=response.profile;saveFallback();renderAll();host.innerHTML=`<div class="success-note">本次检验已保存。${body.correct?'继续做一道迁移题，确认是否稳定。':'记录为不稳定，下一次优先复测同一环节。'}</div>`})}
function setup(){document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>switchView(el.dataset.view)));$('drawer-close').addEventListener('click',()=>$('drawer-backdrop').classList.remove('open'));$('drawer-backdrop').addEventListener('click',e=>{if(e.target.id==='drawer-backdrop')e.currentTarget.classList.remove('open')});document.querySelectorAll('.filter').forEach(el=>el.addEventListener('click',()=>{activeFilter=el.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===el));renderQueue()}));$('bank-search-btn').addEventListener('click',renderBank);$('bank-search').addEventListener('keydown',e=>{if(e.key==='Enter')renderBank()});$('bank-stage').addEventListener('change',renderBank);$('import-open').addEventListener('click',()=>switchView('papers'));$('paper-file').addEventListener('change',e=>{const file=e.target.files[0];if(file&&!$('paper-title').value)$('paper-title').value=file.name.replace(/\.pdf$/i,'');$('import-feedback').textContent=file?`已选择：${file.name}（${Math.round(file.size/1024)} KB）`:''});$('import-submit').addEventListener('click',async()=>{const file=$('paper-file').files[0];const title=$('paper-title').value||'未命名试卷';const exam_date=$('paper-date').value||new Date().toISOString().slice(0,10);if(!file){$('import-feedback').textContent='请先选择 PDF 文件';return}const form=new FormData();form.append('file',file);form.append('title',title);form.append('exam_date',exam_date);const response=await post('/api/papers/import',form,{form:true});if(response?.paper){state.papers.unshift(response.paper);$('import-feedback').textContent='已保存到待确认队列；下一步确认题目切分和得分。'}else{state.papers.unshift({id:'paper-local-'+Date.now(),title,exam_date,score:0,total_score:150,duration:0,source_name:file.name,import_status:'needs_review'});saveFallback();$('import-feedback').textContent='已加入本地演示队列；启动 server.py 后可持久化 PDF。'}renderAll()})}
function setupBankImport(){
  const panel=document.querySelector('.bank-search');
  if(!panel||document.getElementById('bank-import-row'))return;
  const row=document.createElement('div'); row.id='bank-import-row'; row.style.cssText='display:flex;align-items:center;gap:8px;margin-top:12px;padding-top:12px;border-top:1px solid #eef2f0';
  row.innerHTML='<input id="bank-file" type="file" accept="application/json,.json" style="font-size:10px;max-width:240px"><button class="btn secondary" id="bank-import-btn">导入题库 JSON</button><span id="bank-feedback" class="muted"></span>';
  panel.appendChild(row);
  document.getElementById('bank-import-btn').addEventListener('click',async()=>{
    const file=document.getElementById('bank-file').files[0]; const feedback=document.getElementById('bank-feedback');
    if(!file){feedback.textContent='请先选择 JSON 文件';return}
    try{
      const incoming=JSON.parse(await file.text()); const list=Array.isArray(incoming)?incoming:(incoming.questions||[]); const response=await post('/api/bank/import',list);
      if(response){feedback.textContent=`已导入 ${response.imported} 道题目`;await loadState()}
      else{const normalized=list.map((x,i)=>({id:x.id||`local-${Date.now()}-${i}`,source:x.source||'本地题库',stem:x.stem||x.content||x.question||'',difficulty:x.difficulty||3,tags:x.tags||x.keywords||[],fingerprint:x.fingerprint||{}}));state.bank=[...normalized,...state.bank];saveFallback();renderBank();feedback.textContent=`已加入 ${normalized.length} 道题目（演示模式）`}
    }catch{feedback.textContent='JSON 解析失败，请检查题库格式'}
  });
}
function setupConfirmStyles(){const style=document.createElement('style');style.textContent='.confirm-input{width:100%;border:1px solid #dce8e3;border-radius:8px;padding:10px;font:inherit;font-size:11px;background:#fff;color:var(--ink)}';document.head.appendChild(style)}
setupConfirmStyles();setupBankImport();setup();loadState();
